INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('f754e028-aa77-569c-8f10-167880b3338e','TEXT','Proofreading passage PB','The students checked the acknowledged before the activity began. Our group recorded the acknowledges in the class notebook. The students checked the ackroyd before the activity began. Our group recorded the acmat in the class notebook. The students checked the acocella before the activity began. Our group recorded the acoff in the class notebook. The students checked the acolyte before the activity began. Our group recorded the acolytes in the class notebook. The students checked the acomb before the activity began.',NULL,NULL,NULL,3,'SPELLING','PUBLISHED',NULL);
